using System;using UnityEngine;
public sealed class VlabTubing:MonoBehaviour{
 [SerializeField]MeshFilter guide;[SerializeField]Transform connectorA,connectorB;Mesh mesh;Vector2[] uv;Vector3[] vertices;bool routeValid,sealA,sealB;string portA,portB;public float SpacingM{get;private set;}=.16f;public float ControlHeightM{get;private set;}=.12f;bool Ready=>isActiveAndEnabled&&(transform.lossyScale-Vector3.one).sqrMagnitude<1e-10f;public bool LogicalEdgeEnabled=>Ready&&routeValid&&sealA&&sealB&&portA!=null&&portB!=null;public float MinimumBendRadiusM{get;private set;}
 void Awake(){mesh=Instantiate(guide.sharedMesh);mesh.MarkDynamic();guide.sharedMesh=mesh;uv=mesh.uv;vertices=mesh.vertices;TrySetSpan(.16f,.12f);}
 static bool Id(string s){if(string.IsNullOrWhiteSpace(s)||s.Length>128)return false;foreach(char ch in s)if(char.IsControl(ch))return false;return true;}
 public bool TrySetPorts(string a,string b,bool sealedA,bool sealedB){if(!Ready||!routeValid||!Id(a)||!Id(b)||a==b)return false;portA=a;portB=b;sealA=sealedA;sealB=sealedB;return true;}
 public void ClearPorts(){portA=portB=null;sealA=sealB=false;}
 public bool TrySetSpan(float d,float h){if(!Ready||!mesh||!float.IsFinite(d)||!float.IsFinite(h)||d<.079999f||d>.240001f||h<.079999f||h>.200001f)return false;var p0=new Vector3(-d/2,0,.02f);var p1=p0+Vector3.forward*h;var p3=new Vector3(d/2,0,.02f);var p2=p3+Vector3.forward*h;float minimum=float.PositiveInfinity;for(int j=0;j<=16;j++){float t=j/16f,u=1-t;var derivative=3*(p1-p0)*u*u+6*(p2-p1)*u*t+3*(p3-p2)*t*t;var second=6*(p2-2*p1+p0)*u+6*(p3-2*p2+p1)*t;float cross=Vector3.Cross(derivative,second).magnitude;if(cross>1e-10f)minimum=Mathf.Min(minimum,Mathf.Pow(derivative.magnitude,3)/cross);}if(minimum<.008f)return false;
 for(int i=0;i<vertices.Length;i++){float t=uv[i].x,u=1-t;var center=p0*u*u*u+3*p1*u*u*t+3*p2*u*t*t+p3*t*t*t;var derivative=3*(p1-p0)*u*u+6*(p2-p1)*u*t+3*(p3-p2)*t*t;var side=Vector3.Cross(derivative.normalized,Vector3.up).normalized;float angle=(uv[i].y%2)*Mathf.PI*2;float radius=uv[i].y>=1.5f?.002f/Mathf.Cos(Mathf.PI/8):.004f;var p=center+radius*(Vector3.up*Mathf.Cos(angle)+side*Mathf.Sin(angle));vertices[i]=guide.transform.InverseTransformPoint(transform.TransformPoint(new Vector3(p.x,p.y,-p.z)));}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateBounds();connectorA.localPosition=Vector3.left*d*.5f;connectorB.localPosition=Vector3.right*d*.5f;SpacingM=d;ControlHeightM=h;MinimumBendRadiusM=minimum;routeValid=true;return true;}
 void OnDisable()=>ClearPorts();void OnDestroy(){if(mesh)Destroy(mesh);}
 // shortcut: prescribed planar symmetric hollow route and explicit caller seal assertions; logical edge is not airtightness, pressure, flow or chemical proof.
}
